/* Star Wars set additions — cards appended after star-wars.js.
   (star-wars.js exceeds the push size limit, so remaining cards live here instead of being
   edited into it. Must stay directly after 'star-wars.js' in sets/manifest.js.) */
(function () {
  var S = window.CardSets && window.CardSets.get('star-wars');
  if (!S) return;
  var extra = [{"name":"Ryloth","rarity":"uncommon","id":"ryloth","subtitle":"Planets & Locations","details":"Homeworld of the Twi'leks, Ryloth endured a Separatist occupation in the Clone Wars, resisted by Cham Syndulla and later by his daughter Hera.","image":"https://vignette.wikia.nocookie.net/starwars/images/9/96/Ryloth-Homecoming.png/revision/latest/scale-to-width-down/600?cb=20200517155255"},{"name":"Dathomir","rarity":"uncommon","id":"dathomir","subtitle":"Planets & Locations","details":"A misty, red-lit world of the Nightsisters, Dathomir was Mother Talzin's home and the place where Darth Maul and Savage Opress were remade.","image":"https://vignette.wikia.nocookie.net/starwars/images/3/34/DathomirJFO.jpg/revision/latest/scale-to-width-down/600?cb=20200222032237"},{"name":"Lothal","rarity":"uncommon","id":"lothal","subtitle":"Planets & Locations","details":"A grassy Outer Rim farming world, Lothal endured Imperial occupation and factories until Ezra Bridger and the Ghost crew helped drive it free.","image":"https://vignette.wikia.nocookie.net/starwars/images/a/ac/Lothal-SM.png/revision/latest/scale-to-width-down/600?cb=20200909025000"},{"name":"Atollon","rarity":"uncommon","id":"atollon","subtitle":"Planets & Locations","details":"A remote, rocky world ringed by a coral maze, Atollon hid the Rebels' Chopper Base until Grand Admiral Thrawn found and besieged it there.","image":"https://vignette.wikia.nocookie.net/starwars/images/a/ac/Atollon_DoR.png/revision/latest/scale-to-width-down/600?cb=20170926062653"},{"name":"Jedha","rarity":"uncommon","id":"jedha","subtitle":"Planets & Locations","details":"A cold desert moon sacred to believers in the Force, Jedha's holy city held kyber crystal temples before the Death Star tested its superlaser there.","image":"https://vignette.wikia.nocookie.net/starwars/images/3/38/Jedha-2015StarWars38.png/revision/latest/scale-to-width-down/600?cb=20240114021800"},{"name":"Eadu","rarity":"uncommon","id":"eadu","subtitle":"Planets & Locations","details":"A storm-lashed, rocky world, Eadu hosted the Empire's secret weapons research facility where Galen Erso worked on the Death Star's superlaser.","image":"https://vignette.wikia.nocookie.net/starwars/images/3/38/Eadu-SWCT.png/revision/latest/scale-to-width-down/600?cb=20181010053249"},{"name":"Kessel","rarity":"uncommon","id":"kessel","subtitle":"Planets & Locations","details":"A spice-mining world of tunnels and slave labor, Kessel was the source of the coaxium run that made Han Solo and the Millennium Falcon legendary.","image":"https://vignette.wikia.nocookie.net/starwars/images/e/e5/Kessel-SWCT.png/revision/latest/scale-to-width-down/600?cb=20181015054435"},{"name":"Corellia","rarity":"uncommon","id":"corellia","subtitle":"Planets & Locations","details":"A famed shipbuilding world of sprawling industrial cities, Corellia was Han Solo's harsh home, where he grew up in the White Worms gang's sewers.","image":"https://vignette.wikia.nocookie.net/starwars/images/f/fe/Corellia-2025ToppsSWHyperspace.png/revision/latest/scale-to-width-down/600?cb=20260220041026"},{"name":"Mimban","rarity":"uncommon","id":"mimban","subtitle":"Planets & Locations","details":"A muddy, swampy world fought over by the Empire, Mimban was where Han Solo served as an infantry mudtrooper before deserting to join Beckett.","image":"https://vignette.wikia.nocookie.net/starwars/images/0/05/Mimban.png/revision/latest/scale-to-width-down/600?cb=20181015054558"},{"name":"Vandor","rarity":"uncommon","id":"vandor","subtitle":"Planets & Locations","details":"An icy mountain world crossed by Imperial conveyex trains, Vandor hosted the coaxium heist where Beckett's crew first crossed paths with Han Solo.","image":"https://vignette.wikia.nocookie.net/starwars/images/c/cb/Vandor.png/revision/latest/scale-to-width-down/600?cb=20181015054828"},{"name":"Savareen","rarity":"uncommon","id":"savareen","subtitle":"Planets & Locations","details":"A dry, coastal world of refineries, Savareen processed raw coaxium and was where Han Solo faced Tobias Beckett and outplayed Dryden Vos's syndicate.","image":"https://vignette.wikia.nocookie.net/starwars/images/f/fd/Savareen.png/revision/latest/scale-to-width-down/600?cb=20181015054746"},{"name":"DL-44 Heavy Blaster Pistol","rarity":"uncommon","id":"dl-44-heavy-blaster-pistol","subtitle":"Weapons, Artifacts & Tech","details":"Han Solo's signature heavy blaster pistol, the DL-44 packed unusual punch for its size and rode in a quick-draw holster at his hip for decades.","image":"https://vignette.wikia.nocookie.net/starwars/images/0/0f/Han_Solo_DL-44_SWIconsHS.png/revision/latest/scale-to-width-down/600?cb=20190201010326"},{"name":"E-11 Blaster Rifle","rarity":"uncommon","id":"e-11-blaster-rifle","subtitle":"Weapons, Artifacts & Tech","details":"The standard Imperial stormtrooper rifle, the E-11 was a compact, reliable blaster carried from Death Star corridors to battlefields everywhere.","image":"https://vignette.wikia.nocookie.net/starwars/images/b/b3/E11BlasterRifle-CGSWG.png/revision/latest/scale-to-width-down/600?cb=20241221200343"},{"name":"Bowcaster","rarity":"uncommon","id":"bowcaster","subtitle":"Weapons, Artifacts & Tech","details":"A traditional Wookiee weapon blending bow and blaster, Chewbacca's bowcaster fired explosive quarrels with a force that impressed even Han Solo.","image":"https://vignette.wikia.nocookie.net/starwars/images/a/a9/Bowcaster_DICE.png/revision/latest/scale-to-width-down/600?cb=20220911002039"},{"name":"Thermal Detonator","rarity":"uncommon","id":"thermal-detonator","subtitle":"Weapons, Artifacts & Tech","details":"A small, powerful explosive with a thumb trigger, a thermal detonator was the threat Leia, disguised as Boushh, used to bargain with Jabba the Hutt.","image":"https://vignette.wikia.nocookie.net/starwars/images/6/66/ThermalDetonator-GotR2022.png/revision/latest/scale-to-width-down/600?cb=20251224033240"},{"name":"Holocron","rarity":"uncommon","id":"holocron","subtitle":"Weapons, Artifacts & Tech","details":"An ancient data device opened through the Force, a Jedi holocron stored teachings and secrets, its crystal memory accessible only to Force users.","image":"https://vignette.wikia.nocookie.net/starwars/images/6/66/HolocronsCrystals-SWGE.png/revision/latest/scale-to-width-down/600?cb=20200412230628"},{"name":"Sith Holocron","rarity":"uncommon","id":"sith-holocron","subtitle":"Weapons, Artifacts & Tech","details":"A pyramid-shaped Sith artifact storing dark side lore, the Sith holocron Ezra Bridger found on Malachor whispered promises of power and many secrets.","image":"https://vignette.wikia.nocookie.net/starwars/images/7/74/MalachorSithHolocron-DVSWE.png/revision/latest/scale-to-width-down/600?cb=20221122061118"},{"name":"Beskar Steel","rarity":"uncommon","id":"beskar-steel","subtitle":"Weapons, Artifacts & Tech","details":"A legendary Mandalorian iron, beskar could resist blaster fire and even lightsaber strikes, forged into armor passed down through clans for generations.","image":"https://vignette.wikia.nocookie.net/starwars/images/1/12/Beskar-TSWB.png/revision/latest/scale-to-width-down/600?cb=20211225211302"},{"name":"Death Star Plans","rarity":"uncommon","id":"death-star-plans","subtitle":"Weapons, Artifacts & Tech","details":"The stolen technical readouts of the Death Star, carried by Princess Leia, R2-D2, and Jyn Erso's team, revealed the station's fatal reactor weakness.","image":"https://vignette.wikia.nocookie.net/starwars/images/6/64/DeathStarPlans-SW100Objects.png/revision/latest/scale-to-width-down/400?cb=20230422015559"},{"name":"Lightsaber Pike","rarity":"uncommon","id":"lightsaber-pike","subtitle":"Weapons, Artifacts & Tech","details":"A double-bladed lightsaber on a long staff, the pike was wielded by Jedi Temple Guards, its yellow blades marking their anonymous ceremonial role.","image":"https://vignette.wikia.nocookie.net/starwars/images/0/08/JediTempleGuardPyke-TLC.png/revision/latest/scale-to-width-down/600?cb=20221004202653"},{"name":"Electrostaff","rarity":"uncommon","id":"electrostaff","subtitle":"Weapons, Artifacts & Tech","details":"A staff weapon crackling with purple energy, the electrostaff was carried by Separatist MagnaGuards and could block blows from a Jedi's lightsaber.","image":"https://vignette.wikia.nocookie.net/starwars/images/e/e5/Electrostaff-SW.jpg/revision/latest/scale-to-width-down/600?cb=20150905055830"},{"name":"Gaderffii Stick","rarity":"uncommon","id":"gaderffii-stick","subtitle":"Weapons, Artifacts & Tech","details":"A traditional Tusken Raider weapon with a blade and club end, the gaderffii stick was crafted by each Sand Person as a rite of passage on Tatooine.","image":"https://vignette.wikia.nocookie.net/starwars/images/2/24/GaderffiSticks-SW100Objects.png/revision/latest/scale-to-width-down/600?cb=20230419211634"},{"name":"Vibroblade","rarity":"uncommon","id":"vibroblade","subtitle":"Weapons, Artifacts & Tech","details":"A blade weapon humming with ultrasonic vibration, vibroblades cut far beyond a plain edge and were common sidearms for soldiers and bounty hunters.","image":"https://vignette.wikia.nocookie.net/starwars/images/b/bb/Vibroblade-Ch23TheSpies.png/revision/latest/scale-to-width-down/600?cb=20250124025238"},{"name":"Dewback","rarity":"uncommon","id":"dewback","subtitle":"Creatures & Species","details":"A thick-skinned, four-legged reptile native to Tatooine, dewbacks served as hardy mounts for Imperial sandtrooper patrols in the desert heat.","image":"https://vignette.wikia.nocookie.net/starwars/images/7/7d/Dewback-CGSWG.png/revision/latest/scale-to-width-down/600?cb=20241125073047"},{"name":"Porg","rarity":"uncommon","id":"porg","subtitle":"Creatures & Species","details":"Small, wide-eyed seabirds native to Ahch-To, porgs nested around the first Jedi village and famously swarmed the Millennium Falcon during its visit.","image":"https://vignette.wikia.nocookie.net/starwars/images/e/ef/Porg-SWLS.png/revision/latest/scale-to-width-down/600?cb=20241201183008"},{"name":"Ewok","rarity":"uncommon","id":"ewok","subtitle":"Creatures & Species","details":"Small, furry inhabitants of Endor's forest moon, Ewoks lived in treetop villages and helped the Rebels defeat the Empire with traps and courage.","image":"https://vignette.wikia.nocookie.net/starwars/images/a/a8/Ewoks_Encyclopedia.png/revision/latest/scale-to-width-down/600?cb=20210904221240"},{"name":"Jawa","rarity":"uncommon","id":"jawa","subtitle":"Creatures & Species","details":"Short, hooded scavengers of Tatooine, Jawas roamed the desert in sandcrawlers, trading salvaged droids and parts while chattering in their own tongue.","image":"https://vignette.wikia.nocookie.net/starwars/images/b/bd/Jawas-SWApp.png/revision/latest/scale-to-width-down/600?cb=20251014234834"},{"name":"Tusken Raider","rarity":"uncommon","id":"tusken-raider","subtitle":"Creatures & Species","details":"Nomadic Sand People of Tatooine's deserts, Tusken Raiders wrapped themselves head to toe in cloth and fiercely defended their territory and traditions.","image":"https://vignette.wikia.nocookie.net/starwars/images/2/2c/TuskenFamily-TSWB.png/revision/latest/scale-to-width-down/600?cb=20211225202021"},{"name":"Wookiee","rarity":"uncommon","id":"wookiee","subtitle":"Creatures & Species","details":"Tall, long-lived, fur-covered beings from Kashyyyk, Wookiees were famed for their strength, loyalty, and skill as mechanics, warriors, and co-pilots.","image":"https://vignette.wikia.nocookie.net/starwars/images/1/1e/Chewbacca-Fathead.png/revision/latest/scale-to-width-down/600?cb=20161108052810"},{"name":"Twi'lek","rarity":"uncommon","id":"twilek","subtitle":"Creatures & Species","details":"A graceful species with twin head-tails called lekku, Twi'leks came from Ryloth and appeared across the galaxy as dancers, pilots, and rebels.","image":"https://vignette.wikia.nocookie.net/starwars/images/5/54/Twileks.png/revision/latest/scale-to-width-down/600?cb=20151229035344"},{"name":"Rodian","rarity":"uncommon","id":"rodian","subtitle":"Creatures & Species","details":"A green-skinned species with large eyes and antennae, Rodians from Rodia were famed as skilled hunters, and Greedo faced Han Solo in Mos Eisley.","image":"https://vignette.wikia.nocookie.net/starwars/images/d/d3/Rodian_DICE.png/revision/latest/scale-to-width-down/600?cb=20260227044626"},{"name":"Star Wars: Episode II – Attack of the Clones","rarity":"uncommon","id":"star-wars-episode-ii-attack-of-the-clones","subtitle":"Films & Series","details":"The second prequel follows Obi-Wan Kenobi uncovering a clone army and Anakin Skywalker's secret marriage, ending with the first Clone Wars battle.","image":"https://vignette.wikia.nocookie.net/starwars/images/d/dd/Attack-Clones-Poster.jpg/revision/latest/scale-to-width-down/600?cb=20250617225730"},{"name":"Star Wars: Episode VII – The Force Awakens","rarity":"uncommon","id":"star-wars-episode-vii-the-force-awakens","subtitle":"Films & Series","details":"Set decades after Endor, this chapter introduces Rey, Finn, and Poe as the Resistance searches for Luke Skywalker and faces Kylo Ren's First Order.","image":"https://vignette.wikia.nocookie.net/starwars/images/f/fd/Star_Wars_Episode_VII_The_Force_Awakens.jpg/revision/latest/scale-to-width-down/600?cb=20250618012820"},{"name":"Star Wars: Episode VIII – The Last Jedi","rarity":"uncommon","id":"star-wars-episode-viii-the-last-jedi","subtitle":"Films & Series","details":"Rey trains with a reluctant Luke Skywalker on Ahch-To while the Resistance flees the First Order, ending with hope rekindled from a spark of legend.","image":"https://vignette.wikia.nocookie.net/starwars/images/1/12/TheLastJediTheatricalPoster.jpg/revision/latest/scale-to-width-down/600?cb=20171010002420"},{"name":"Star Wars: Episode IX – The Rise of Skywalker","rarity":"uncommon","id":"star-wars-episode-ix-the-rise-of-skywalker","subtitle":"Films & Series","details":"The sequel trilogy's finale sees Rey confront her heritage and a returned Palpatine while the Resistance rallies a galaxy-wide fleet at Exegol.","image":"https://vignette.wikia.nocookie.net/starwars/images/4/4c/TROSOneSheet.jpg/revision/latest/scale-to-width-down/600?cb=20191022091806"},{"name":"Solo: A Star Wars Story","rarity":"uncommon","id":"solo-a-star-wars-story","subtitle":"Films & Series","details":"This origin story follows young Han Solo from Corellia's streets to the Kessel Run, meeting Chewbacca and Lando Calrissian along the way.","image":"https://vignette.wikia.nocookie.net/starwars/images/a/a9/Solo_A_Star_Wars_Story_Theatrical_Poster.png/revision/latest/scale-to-width-down/600?cb=20180409011120"},{"name":"Andor","rarity":"uncommon","id":"andor","subtitle":"Films & Series","details":"This series follows Cassian Andor's path from thief to Rebel spy, tracing the sacrifices and prison breaks that forged the early Rebellion.","image":"https://vignette.wikia.nocookie.net/starwars/images/3/3b/Andor_Season_One_poster.jpg/revision/latest/scale-to-width-down/600?cb=20220623212226"},{"name":"The Trench Run","rarity":"uncommon","id":"the-trench-run","subtitle":"Battles & Iconic Moments","details":"Luke Skywalker's attack run down the Death Star's trench ended with him trusting the Force, firing the proton torpedoes that destroyed the station.","image":"https://vignette.wikia.nocookie.net/starwars/images/0/00/Battle_of_Yavin_OFL.png/revision/latest/scale-to-width-down/600?cb=20190217010540"},{"name":"Rescue of Princess Leia","rarity":"uncommon","id":"rescue-of-princess-leia","subtitle":"Battles & Iconic Moments","details":"Luke, Han, Chewbacca, and Obi-Wan infiltrated the Death Star in stormtrooper disguises to free Princess Leia from her detention cell block.","image":"https://vignette.wikia.nocookie.net/starwars/images/b/b0/Kenobivaderanh.png/revision/latest/scale-to-width-down/600?cb=20130313220708"},{"name":"Duel on Bespin","rarity":"uncommon","id":"duel-on-bespin","subtitle":"Battles & Iconic Moments","details":"On Cloud City, Darth Vader dueled Luke Skywalker through carbon-freezing chambers and revealed the shattering truth that he was Luke's father.","image":"https://vignette.wikia.nocookie.net/starwars/images/c/cd/CloudCityDuel-TSWB.png/revision/latest/scale-to-width-down/600?cb=20211226193509"},{"name":"Battle of Coruscant","rarity":"uncommon","id":"battle-of-coruscant","subtitle":"Battles & Iconic Moments","details":"The Clone Wars' vast opening battle over Coruscant saw Anakin and Obi-Wan fight through Separatist fleets to rescue Chancellor Palpatine.","image":"https://vignette.wikia.nocookie.net/starwars/images/3/34/Spacebattle.jpg/revision/latest/scale-to-width-down/600?cb=20091019154628"},{"name":"Order 66","rarity":"uncommon","id":"order-66","subtitle":"Battles & Iconic Moments","details":"Palpatine's secret command turned clone troopers against their Jedi generals across the galaxy, nearly wiping out the Jedi Order in a single day.","image":"https://vignette.wikia.nocookie.net/starwars/images/4/44/End_Days.jpg/revision/latest/scale-to-width-down/600?cb=20111028234105"},{"name":"Battle of Exegol","rarity":"uncommon","id":"battle-of-exegol","subtitle":"Battles & Iconic Moments","details":"A citizen fleet from across the galaxy joined the Resistance at Exegol, where Rey faced Palpatine and the Sith Eternal's Final Order armada.","image":"https://vignette.wikia.nocookie.net/starwars/images/3/30/Battle_of_Exegol.jpg/revision/latest/scale-to-width-down/600?cb=20230129165110"},{"name":"Siege of Mandalore","rarity":"uncommon","id":"siege-of-mandalore","subtitle":"Battles & Iconic Moments","details":"Ahsoka Tano led Republic forces to capture Maul on Mandalore in the Clone Wars' final days, a victory overtaken by the tragedy of Order 66.","image":"https://vignette.wikia.nocookie.net/starwars/images/3/3e/SiegeOfMandaloreRaging-TPA.png/revision/latest/scale-to-width-down/600?cb=20200430045817"},{"name":"Battle of Jakku","rarity":"uncommon","id":"battle-of-jakku","subtitle":"Battles & Iconic Moments","details":"The Galactic Civil War's final major battle raged over Jakku a year after Endor, littering its deserts with the wreckage Rey later scavenged.","image":"https://vignette.wikia.nocookie.net/starwars/images/5/51/Rebellion_Arrives_at_Jakku.png/revision/latest/scale-to-width-down/600?cb=20171214072500"},{"name":"Wicket W. Warrick","rarity":"common","id":"wicket-w-warrick","subtitle":"Heroes & Rebels","details":"A curious young Ewok scout, Wicket befriended Princess Leia in Endor's forests and helped his tribe join the Rebels' fight against the Empire.","image":"https://vignette.wikia.nocookie.net/starwars/images/a/aa/Wicket-2024Base.png/revision/latest/scale-to-width-down/600?cb=20251026210916"},{"name":"Chief Chirpa","rarity":"common","id":"chief-chirpa","subtitle":"Heroes & Rebels","details":"The wise elder leader of Bright Tree Village, Chief Chirpa carried a staff of authority and agreed to ally his Ewoks with the Rebel strike team.","image":"https://vignette.wikia.nocookie.net/starwars/images/7/77/ChiefChirpa-JtR.png/revision/latest/scale-to-width-down/600?cb=20251225060324"},{"name":"Logray","rarity":"common","id":"logray","subtitle":"Heroes & Rebels","details":"The Ewok medicine man of Bright Tree Village, Logray wore a tall headdress of bones and feathers and at first ordered the Rebel captives sacrificed.","image":"https://vignette.wikia.nocookie.net/starwars/images/5/51/Logray-2023Base.png/revision/latest/scale-to-width-down/600?cb=20251126030821"},{"name":"Teebo","rarity":"common","id":"teebo","subtitle":"Heroes & Rebels","details":"A young Ewok warrior and poet, Teebo wore a headdress with animal bones and fought bravely alongside his tribe in the ground battle on Endor.","image":"https://vignette.wikia.nocookie.net/starwars/images/9/90/Teebo-DB.png/revision/latest/scale-to-width-down/600?cb=20150920212104"},{"name":"Paploo","rarity":"common","id":"paploo","subtitle":"Heroes & Rebels","details":"A daring young Ewok, Paploo famously stole an Imperial speeder bike on Endor, drawing biker scouts away from the shield generator bunker entrance.","image":"https://vignette.wikia.nocookie.net/starwars/images/d/d5/EwokWarrior-SoH.png/revision/latest/scale-to-width-down/600?cb=20190428015441"},{"name":"Owen Lars","rarity":"common","id":"owen-lars","subtitle":"Heroes & Rebels","details":"Luke Skywalker's stern uncle, moisture farmer Owen Lars raised Luke on Tatooine and tried to shield him from the truth about his father's fate.","image":"https://vignette.wikia.nocookie.net/starwars/images/e/eb/OwenCardTrader.png/revision/latest/scale-to-width-down/600?cb=20241208055940"},{"name":"Beru Lars","rarity":"common","id":"beru-lars","subtitle":"Heroes & Rebels","details":"Luke's kind aunt, Beru Lars raised him on the Tatooine moisture farm and quietly believed the restless boy was meant for more than farm life.","image":"https://vignette.wikia.nocookie.net/starwars/images/c/cc/BeruCardTrader.png/revision/latest/scale-to-width-down/600?cb=20241224004045"},{"name":"Shmi Skywalker","rarity":"common","id":"shmi-skywalker","subtitle":"Heroes & Rebels","details":"Anakin Skywalker's selfless mother, Shmi raised her son in slavery on Tatooine and told Qui-Gon Jinn there was no father, a mystery of the Force.","image":"https://vignette.wikia.nocookie.net/starwars/images/6/6c/ShmiSkywalkerLars-Databank.jpg/revision/latest/scale-to-width-down/600?cb=20171114023541"},{"name":"Cliegg Lars","rarity":"common","id":"cliegg-lars","subtitle":"Heroes & Rebels","details":"A Tatooine moisture farmer who freed and married Shmi Skywalker, Cliegg Lars lost a leg to Tusken Raiders while trying to rescue her from captivity.","image":"https://vignette.wikia.nocookie.net/starwars/images/3/36/ClieggLarsHS-SWE.jpg/revision/latest/scale-to-width-down/600?cb=20180513065414"},{"name":"Breha Organa","rarity":"common","id":"breha-organa","subtitle":"Heroes & Rebels","details":"Queen of Alderaan and Leia's adoptive mother, Breha Organa raised the princess alongside Bail, giving her a childhood of love and public service.","image":"https://vignette.wikia.nocookie.net/starwars/images/6/62/BrehaOrgana-DoRTVG.png/revision/latest/scale-to-width-down/600?cb=20250108072726"},{"name":"Raymus Antilles","rarity":"common","id":"raymus-antilles","subtitle":"Heroes & Rebels","details":"Captain of the Tantive IV in both Rogue One and A New Hope, Raymus Antilles served Bail Organa loyally and was choked by Darth Vader aboard his ship.","image":"https://vignette.wikia.nocookie.net/starwars/images/8/80/Raymus_card_trader.png/revision/latest/scale-to-width-down/600?cb=20251107052511"},{"name":"Jan Dodonna","rarity":"common","id":"jan-dodonna","subtitle":"Heroes & Rebels","details":"General Jan Dodonna planned the Rebel attack on the first Death Star, briefing pilots at Yavin 4 on the trench run and the exhaust port weakness.","image":"https://vignette.wikia.nocookie.net/starwars/images/1/1e/Jan_Dodonna-SW_Card_Trader.png/revision/latest/scale-to-width-down/600?cb=20251219020642"},{"name":"Carlist Rieekan","rarity":"common","id":"carlist-rieekan","subtitle":"Heroes & Rebels","details":"General Carlist Rieekan commanded Echo Base on Hoth, ordering its evacuation when Imperial walkers advanced and buying the Rebels time to escape.","image":"https://vignette.wikia.nocookie.net/starwars/images/e/e1/GeneralRieekan-BaseSeries5.png/revision/latest/scale-to-width-down/600?cb=20251111144941"},{"name":"Crix Madine","rarity":"common","id":"crix-madine","subtitle":"Heroes & Rebels","details":"Former Imperial officer Crix Madine defected to the Rebellion and planned the strike team mission that disabled the shield generator on Endor.","image":"https://vignette.wikia.nocookie.net/starwars/images/2/28/MadineHS-ROTJ.png/revision/latest/scale-to-width-down/600?cb=20130403231243"},{"name":"Meena Tills","rarity":"common","id":"meena-tills","subtitle":"Heroes & Rebels","details":"Mon Calamari Senator Meena Tills represented her people in the Galactic Senate during the Clone Wars, working alongside Padme Amidala and Bail Organa.","image":"https://vignette.wikia.nocookie.net/starwars/images/2/21/MeenaTills-BaseSeries4.png/revision/latest/scale-to-width-down/600?cb=20251127033803"},{"name":"Cham Syndulla","rarity":"common","id":"cham-syndulla","subtitle":"Heroes & Rebels","details":"Freedom fighter Cham Syndulla led resistance on Ryloth against Separatist and Imperial occupation, and was the father of Rebel pilot Hera Syndulla.","image":"https://vignette.wikia.nocookie.net/starwars/images/1/1c/Cham_Syndulla_CT.png/revision/latest/scale-to-width-down/600?cb=20230126145036"},{"name":"Numa","rarity":"common","id":"numa","subtitle":"Heroes & Rebels","details":"A young Twi'lek girl on Ryloth, Numa befriended clone troopers Waxer and Boil during the Clone Wars and later inspired rebels fighting the Empire.","image":"https://vignette.wikia.nocookie.net/starwars/images/3/32/Adult_numa_-_SW_Card_Trader.png/revision/latest/scale-to-width-down/600?cb=20251111035016"},{"name":"Waxer","rarity":"common","id":"waxer","subtitle":"Heroes & Rebels","details":"Clone trooper Waxer served in the 212th Attack Battalion, fought on Ryloth and Geonosis, and showed kindness to the Twi'lek orphan Numa.","image":"https://vignette.wikia.nocookie.net/starwars/images/a/aa/WaxerHS-SWE.png/revision/latest/scale-to-width-down/600?cb=20240919013944"},{"name":"Boil","rarity":"common","id":"boil","subtitle":"Heroes & Rebels","details":"Clone trooper Boil served with Waxer in the 212th Attack Battalion, keeping watch over Numa on Ryloth despite his gruff manner with civilians.","image":"https://vignette.wikia.nocookie.net/starwars/images/d/d4/BoilHS-SWE.png/revision/latest/scale-to-width-down/600?cb=20220910223408"},{"name":"Hardcase","rarity":"common","id":"hardcase","subtitle":"Heroes & Rebels","details":"Energetic clone trooper Hardcase served in the 501st Legion, fought with a rotary blaster at Umbara, and sacrificed himself to destroy a supply ship.","image":"https://vignette.wikia.nocookie.net/starwars/images/3/33/HardcaseHS-POD.png/revision/latest/scale-to-width-down/600?cb=20121127022520"},{"name":"Tup","rarity":"common","id":"tup","subtitle":"Heroes & Rebels","details":"Clone trooper Tup served in the 501st Legion until his inhibitor chip malfunctioned on Ringo Vinda, causing him to fatally shoot Jedi General Tiplar.","image":"https://vignette.wikia.nocookie.net/starwars/images/3/38/TupHS-POD.png/revision/latest/scale-to-width-down/600?cb=20121127023016"},{"name":"Jesse","rarity":"common","id":"jesse","subtitle":"Heroes & Rebels","details":"Clone trooper Jesse rose to ARC trooper in the 501st Legion, fought at Umbara and Saleucami, and remained loyal to the Empire after Order 66.","image":"https://vignette.wikia.nocookie.net/starwars/images/5/51/Jesse_ARC_trooper.png/revision/latest/scale-to-width-down/600?cb=20200321190211"},{"name":"Seventh Sister","rarity":"common","id":"seventh-sister","subtitle":"Villains & Empire","details":"A Mirialan Inquisitor, the Seventh Sister hunted rebels with ID9 seeker droids and dueled Ahsoka Tano and Kanan Jarrus before falling to Maul on Malachor.","image":"https://vignette.wikia.nocookie.net/starwars/images/b/b5/Seventh_Sister.png/revision/latest/scale-to-width-down/600?cb=20250225235949"},{"name":"Second Sister","rarity":"common","id":"second-sister","subtitle":"Villains & Empire","details":"Inquisitor Trilla Suduri, the Second Sister, was a former Padawan turned Jedi hunter who pursued Cere Junda, Cal Kestis and the crew of the Stinger Mantis.","image":"https://vignette.wikia.nocookie.net/starwars/images/b/bd/Trilla-JFO.png/revision/latest/scale-to-width-down/600?cb=20200222170758"},{"name":"Third Sister","rarity":"common","id":"third-sister","subtitle":"Villains & Empire","details":"Reva Sevander, the Third Sister, survived Order 66 as a youngling and became an Inquisitor obsessed with hunting Obi-Wan Kenobi to reach Darth Vader.","image":"https://vignette.wikia.nocookie.net/starwars/images/f/f8/ThirdSister-OWK1.png/revision/latest/scale-to-width-down/600?cb=20220703193146"},{"name":"Pre Vizsla","rarity":"common","id":"pre-vizsla","subtitle":"Villains & Empire","details":"Pre Vizsla led Death Watch from Concordia, wielded the black-bladed Darksaber as a descendant of Tarre Vizsla, and died dueling Maul on Mandalore.","image":"https://vignette.wikia.nocookie.net/starwars/images/f/fc/PreVizsla-Eminence.png/revision/latest/scale-to-width-down/600?cb=20131024191840"},{"name":"Gar Saxon","rarity":"common","id":"gar-saxon","subtitle":"Villains & Empire","details":"Mandalorian warrior Gar Saxon served Maul's Shadow Collective and later became Imperial Viceroy of Mandalore, enforcing the Empire's rule by force.","image":"https://vignette.wikia.nocookie.net/starwars/images/8/80/Gar_Saxon-FA.jpg/revision/latest/scale-to-width-down/600?cb=20250416004847"},{"name":"Lott Dod","rarity":"common","id":"lott-dod","subtitle":"Villains & Empire","details":"Neimoidian Senator Lott Dod represented the Trade Federation in the Galactic Senate, opposing measures that threatened his guild's profits and power.","image":"https://vignette.wikia.nocookie.net/starwars/images/2/24/LottEncyclopedia.png/revision/latest/scale-to-width-down/600?cb=20231020023411"},{"name":"San Hill","rarity":"common","id":"san-hill","subtitle":"Villains & Empire","details":"Muun chairman San Hill led the InterGalactic Banking Clan, pledged its resources to Count Dooku's Separatists, and helped fund the Clone Wars.","image":"https://vignette.wikia.nocookie.net/starwars/images/6/63/SanHill-BaseSeries5.png/revision/latest/scale-to-width-down/600?cb=20251107064755"},{"name":"Shu Mai","rarity":"common","id":"shu-mai","subtitle":"Villains & Empire","details":"Gossam president Shu Mai led the Commerce Guild in the Separatist Council, backing Count Dooku while protecting her guild's wealth and trade interests.","image":"https://vignette.wikia.nocookie.net/starwars/images/6/68/ShuMai-oldDb.png/revision/latest/scale-to-width-down/600?cb=20251229153942"},{"name":"Passel Argente","rarity":"common","id":"passel-argente","subtitle":"Villains & Empire","details":"Koorivar Magistrate Passel Argente led the Corporate Alliance in the Separatist Council, lending its droid forces and credits to the Confederacy.","image":"https://vignette.wikia.nocookie.net/starwars/images/a/ac/Passel-Argente-SWCT.png/revision/latest/scale-to-width-down/600?cb=20251219011759"},{"name":"Po Nudo","rarity":"common","id":"po-nudo","subtitle":"Villains & Empire","details":"Aqualish Senator Po Nudo left the Republic to join the Separatist Council, representing his sector until Darth Vader arrived on Mustafar.","image":"https://vignette.wikia.nocookie.net/starwars/images/5/5b/PoNudo-WOSW.png/revision/latest/scale-to-width-down/600?cb=20241006044410"},{"name":"Tikkes","rarity":"common","id":"tikkes","subtitle":"Villains & Empire","details":"Quarren Senator Tikkes represented Mon Cala interests before joining the Separatists, backing a Confederacy that promised his people greater power.","image":"https://vignette.wikia.nocookie.net/starwars/images/7/73/Tikkes.jpg/revision/latest/scale-to-width-down/600?cb=20100117033839"},{"name":"Denaria Kee","rarity":"common","id":"denaria-kee","subtitle":"Villains & Empire","details":"Denaria Kee served as chief aide and lieutenant to Corporate Alliance Magistrate Passel Argente, speaking for him in the Separatist Council on Geonosis.","image":"https://vignette.wikia.nocookie.net/starwars/images/d/dc/DenariaKeeForceCollection.png/revision/latest/scale-to-width-down/600?cb=20230603125803"},{"name":"Rogwa Wodrata","rarity":"common","id":"rogwa-wodrata","subtitle":"Villains & Empire","details":"A Holwuff senator, Rogwa Wodrata joined the Separatist movement on Geonosis, appearing among the Separatist leaders gathered by Count Dooku.","image":"https://vignette.wikia.nocookie.net/starwars/images/3/3a/Rogwa_wodrata.jpg/revision/latest/scale-to-width-down/600?cb=20250709170923"},{"name":"Toonbuck Toora","rarity":"common","id":"toonbuck-toora","subtitle":"Villains & Empire","details":"Sy Myrthian Senator Toonbuck Toora backed the Separatist cause on Geonosis, joining other senators disillusioned with the Republic and its Senate.","image":"https://vignette.wikia.nocookie.net/starwars/images/2/2e/ToonToora.png/revision/latest/scale-to-width-down/600?cb=20210509230125"},{"name":"Admiral Trench","rarity":"common","id":"admiral-trench","subtitle":"Villains & Empire","details":"Harch Admiral Trench was a feared Separatist commander who survived several defeats, blockaded Christophsis, and battled Anakin Skywalker repeatedly.","image":"https://vignette.wikia.nocookie.net/starwars/images/0/0e/AdmiralTrenchHS-SWCT.png/revision/latest/scale-to-width-down/600?cb=20251109224429"},{"name":"Lok Durd","rarity":"common","id":"lok-durd","subtitle":"Villains & Empire","details":"Neimoidian general Lok Durd developed the Separatist defoliator weapon, testing the devastating artillery on the Lurmen village on Maridun.","image":"https://vignette.wikia.nocookie.net/starwars/images/d/dd/LokDurd-BaseSeries3.png/revision/latest/scale-to-width-down/600?cb=20251219014424"},{"name":"Whorm Loathsom","rarity":"common","id":"whorm-loathsom","subtitle":"Villains & Empire","details":"Kerkoiden General Whorm Loathsom commanded Separatist droids at Christophsis, surrendering to Obi-Wan Kenobi after a bold Republic counterattack.","image":"https://vignette.wikia.nocookie.net/starwars/images/8/8a/WhormLoathsomHS.png/revision/latest/scale-to-width-down/600?cb=20251203004031"},{"name":"Riff Tamson","rarity":"common","id":"riff-tamson","subtitle":"Villains & Empire","details":"Karkarodon commander Riff Tamson led Separatist forces in the battle for Mon Cala, fighting Prince Lee-Char and the Mon Calamari with brutal ferocity.","image":"https://vignette.wikia.nocookie.net/starwars/images/5/54/RiffTamson-TtG2026.png/revision/latest/scale-to-width-down/600?cb=20260104062614"},{"name":"Gonk Droid","rarity":"common","id":"gonk-droid","subtitle":"Droids","details":"The boxy GNK power droid, universally nicknamed the gonk droid for its low honking sound, shuffles through bases and ships supplying portable power.","image":"https://vignette.wikia.nocookie.net/starwars/images/c/c4/GNKpowerdroid-DB.png/revision/latest/scale-to-width-down/600?cb=20150609065637"},{"name":"Power Droid","rarity":"common","id":"power-droid","subtitle":"Droids","details":"Power droids are walking generators with plug-in ports, recharging starships, vehicles and equipment in hangars, farms and Rebel bases across the galaxy.","image":"https://vignette.wikia.nocookie.net/starwars/images/0/08/EG6series-TGTB.png/revision/latest/scale-to-width-down/600?cb=20251217183558"},{"name":"Medical Droid 2-1B","rarity":"common","id":"medical-droid-2-1b","subtitle":"Droids","details":"The 2-1B surgical droid treated Luke Skywalker in an Echo Base bacta tank on Hoth and later fitted him with a lifelike prosthetic hand.","image":"https://vignette.wikia.nocookie.net/starwars/images/5/5c/21B-MF26.png/revision/latest/scale-to-width-down/600?cb=20260305142651"},{"name":"FX-7 Medical Assistant","rarity":"common","id":"fx-7-medical-assistant","subtitle":"Droids","details":"FX-7 was a wheeled medical assistant droid with many articulated arms, helping 2-1B monitor Luke Skywalker as he recovered in bacta on Hoth.","image":"https://vignette.wikia.nocookie.net/starwars/images/4/43/FX-7-BYOR2D2-19.png/revision/latest/scale-to-width-down/600?cb=20240928023251"},{"name":"Probe Droid","rarity":"common","id":"probe-droid","subtitle":"Droids","details":"Imperial Viper probe droids searched the galaxy for Rebel bases, and one landing on Hoth alerted Darth Vader's fleet to the hidden Echo Base.","image":"https://vignette.wikia.nocookie.net/starwars/images/5/53/Probot-SW100Objects.png/revision/latest/scale-to-width-down/600?cb=20230420005741"},{"name":"Interrogator Droid","rarity":"common","id":"interrogator-droid","subtitle":"Droids","details":"The hovering IT-O interrogator droid carried needles, pincers and sensors, and was used by Darth Vader while questioning Princess Leia on the Death Star.","image":"https://vignette.wikia.nocookie.net/starwars/images/8/8e/IT-O_Interrogation_Unit.jpg/revision/latest/scale-to-width-down/600?cb=20150304052730"},{"name":"Buzz Droid","rarity":"common","id":"buzz-droid","subtitle":"Droids","details":"Pistoeka sabotage droids, called buzz droids, latched onto starfighters in swarms and used saws and drills to tear apart hulls, engines and astromechs.","image":"https://vignette.wikia.nocookie.net/starwars/images/a/af/BuzzDroid-TCWCEJtB.png/revision/latest/scale-to-width-down/600?cb=20241005215840"},{"name":"Vulture Droid","rarity":"common","id":"vulture-droid","subtitle":"Droids","details":"Variable Geometry Self-Propelled Battle Droids, called vulture droids, flew as starfighters and walked on their wings when perched on Separatist ships.","image":"https://vignette.wikia.nocookie.net/starwars/images/6/6b/CISVultureDroid-TCW.png/revision/latest/scale-to-width-down/600?cb=20231010223741"},{"name":"Hyena Bomber Droid","rarity":"common","id":"hyena-bomber-droid","subtitle":"Droids","details":"The hyena bomber was a heavier droid starfighter based on the vulture design, built to carry proton bombs and missiles against Republic targets.","image":"https://vignette.wikia.nocookie.net/starwars/images/0/07/HyenaBomber2-SWE.png/revision/latest/scale-to-width-down/600?cb=20260301054232"},{"name":"Tactical Droid","rarity":"common","id":"tactical-droid","subtitle":"Droids","details":"T-series tactical droids commanded Separatist forces with cold calculation, analyzing Republic tactics aboard ships and on battlefields in the Clone Wars.","image":"https://vignette.wikia.nocookie.net/starwars/images/2/2f/TacticalDroidBlaster-SW.png/revision/latest/scale-to-width-down/600?cb=20260111195952"},{"name":"Commando Droid","rarity":"common","id":"commando-droid","subtitle":"Droids","details":"BX-series commando droids were tougher, smarter Separatist infiltrators that could disguise themselves in clone armor and fight with vibroswords.","image":"https://vignette.wikia.nocookie.net/starwars/images/c/cd/CommandoDroid-CGSWG.png/revision/latest/scale-to-width-down/600?cb=20241214201829"},{"name":"Trade Federation Battleship","rarity":"common","id":"trade-federation-battleship","subtitle":"Starships & Vehicles","details":"Lucrehulk-class Trade Federation battleships formed a blockade around Naboo, controlling vast droid armies from a central command ship in orbit.","image":"https://vignette.wikia.nocookie.net/starwars/images/b/bc/CISLucrehulkBattleship-TCW.png/revision/latest/scale-to-width-down/600?cb=20231010233338"},{"name":"Venator Star Destroyer","rarity":"common","id":"venator-star-destroyer","subtitle":"Starships & Vehicles","details":"The wedge-shaped Venator-class Star Destroyer was the Republic's main Clone Wars capital ship, carrying hundreds of fighters, gunships and clone troops.","image":"https://vignette.wikia.nocookie.net/starwars/images/b/ba/Venator_Databank.jpg/revision/latest/scale-to-width-down/600?cb=20210626060957"},{"name":"Munificent Frigate","rarity":"common","id":"munificent-frigate","subtitle":"Starships & Vehicles","details":"Munificent-class star frigates served the Banking Clan and Separatist navy, using powerful twin turbolasers and advanced communications arrays.","image":"https://vignette.wikia.nocookie.net/starwars/images/3/31/Munificent-class.png/revision/latest/scale-to-width-down/600?cb=20220329023249"},{"name":"Recusant Destroyer","rarity":"common","id":"recusant-destroyer","subtitle":"Starships & Vehicles","details":"Recusant-class destroyers were skeletal Separatist warships built by the Commerce Guild, cheap to mass-produce and often deployed in large numbers.","image":"https://vignette.wikia.nocookie.net/starwars/images/c/c2/Capture_of_Eeth_Koth.png/revision/latest/scale-to-width-down/600"},{"name":"Providence Carrier","rarity":"common","id":"providence-carrier","subtitle":"Starships & Vehicles","details":"Providence-class carrier-destroyers served as Separatist flagships, spacious dreadnoughts carrying droid fighters, bombers and invasion forces.","image":"https://vignette.wikia.nocookie.net/starwars/images/9/9e/Invincible2-TCWs2BR3.png/revision/latest/scale-to-width-down/600?cb=20250404002125"},{"name":"Malevolence","rarity":"common","id":"malevolence","subtitle":"Starships & Vehicles","details":"Grievous's Subjugator-class heavy cruiser Malevolence carried a massive ion pulse cannon that disabled entire Republic fleets, leaving them defenseless.","image":"https://vignette.wikia.nocookie.net/starwars/images/a/ac/Malevolence_firing_ion_pulse.png/revision/latest/scale-to-width-down/600?cb=20120917034715"},{"name":"Invisible Hand","rarity":"common","id":"invisible-hand","subtitle":"Starships & Vehicles","details":"General Grievous's flagship Invisible Hand held Chancellor Palpatine captive over Coruscant and broke apart during a desperate crash landing attempt.","image":"https://vignette.wikia.nocookie.net/starwars/images/3/3d/InvisibleHand-MF75.png/revision/latest/scale-to-width-down/600?cb=20260228051650"},{"name":"Republic Gunship","rarity":"common","id":"republic-gunship","subtitle":"Starships & Vehicles","details":"The LAAT Republic gunship ferried clone troopers into battle, deploying troops through side doors while firing lasers, missiles and beam turrets.","image":"https://vignette.wikia.nocookie.net/starwars/images/b/b9/AirSupport-GRCCP.png/revision/latest/scale-to-width-down/600?cb=20250917045015"},{"name":"Clone Z-95 Starfighter","rarity":"common","id":"clone-z-95-starfighter","subtitle":"Starships & Vehicles","details":"The Clone Z-95 Headhunter was a sturdy Republic starfighter flown by clone pilots, an earlier design in the lineage that led toward the X-wing.","image":"https://vignette.wikia.nocookie.net/starwars/images/5/55/CloneZ-95-EscapeKadavo.jpg/revision/latest/scale-to-width-down/600?cb=20111231021820"},{"name":"V-19 Torrent Starfighter","rarity":"common","id":"v-19-torrent-starfighter","subtitle":"Starships & Vehicles","details":"The V-19 Torrent was an early Clone Wars Republic fighter with folding S-foils, flown at Christophsis and Teth before newer designs replaced it.","image":"https://vignette.wikia.nocookie.net/starwars/images/a/a4/Blue_Squadron_Protector_XW2.png/revision/latest/scale-to-width-down/600?cb=20190205062802"},{"name":"HMP Droid Gunship","rarity":"common","id":"hmp-droid-gunship","subtitle":"Starships & Vehicles","details":"The HMP droid gunship was a heavily armed Separatist air support craft, carrying battle droids and firing missiles at Republic troops and vehicles.","image":"https://vignette.wikia.nocookie.net/starwars/images/e/e9/OnderonOppressor-SWZ.png/revision/latest/scale-to-width-down/600?cb=20200507010731"},{"name":"Eta-2 Interceptor","rarity":"common","id":"eta-2-interceptor","subtitle":"Starships & Vehicles","details":"The small, agile Eta-2 Actis interceptor was flown by Jedi in the Clone Wars, including Anakin Skywalker and Obi-Wan Kenobi at the Battle of Coruscant.","image":"https://vignette.wikia.nocookie.net/starwars/images/9/97/Anakins_Eta-2_SWCT.png/revision/latest/scale-to-width-down/600?cb=20251112041033"},{"name":"Delta-7 Jedi Starfighter","rarity":"common","id":"delta-7-jedi-starfighter","subtitle":"Starships & Vehicles","details":"The Delta-7 Aethersprite Jedi starfighter relied on an external hyperspace ring, flown by Obi-Wan Kenobi on his mission to Kamino and Geonosis.","image":"https://vignette.wikia.nocookie.net/starwars/images/2/28/Delta-7_Interceptor_SoR.png/revision/latest/scale-to-width-down/600?cb=20180805054640"},{"name":"N-1 Naboo Starfighter","rarity":"common","id":"n-1-naboo-starfighter","subtitle":"Starships & Vehicles","details":"The sleek, chrome-and-yellow N-1 Naboo starfighter defended Naboo in the Battle for Naboo, and a rebuilt N-1 later became Din Djarin's fast new ship.","image":"https://vignette.wikia.nocookie.net/starwars/images/6/64/N-1_Starfighter.png/revision/latest/scale-to-width-down/600?cb=20240909024317"},{"name":"Ginivex Starfighter","rarity":"common","id":"ginivex-starfighter","subtitle":"Starships & Vehicles","details":"Asajj Ventress flew a Ginivex-class starfighter with a distinctive fanblade wing that opened in flight, striking swiftly during early Clone Wars missions.","image":"https://vignette.wikia.nocookie.net/starwars/images/0/0b/Ginivex-profile.png/revision/latest/scale-to-width-down/600?cb=20220625172938"},{"name":"Solar Sailer","rarity":"common","id":"solar-sailer","subtitle":"Starships & Vehicles","details":"Count Dooku's Punworcca 116-class solar sailer traveled by a vast sail catching interstellar energy, carrying him from Geonosis to Coruscant in secret.","image":"https://vignette.wikia.nocookie.net/starwars/images/f/f5/DookusSolarSailer-SWBC61.png/revision/latest/scale-to-width-down/600?cb=20240218052159"},{"name":"Geonosian Starfighter","rarity":"common","id":"geonosian-starfighter","subtitle":"Starships & Vehicles","details":"Nantex-class Geonosian starfighters defended Geonosis with tractor-beam-guided laser cannons, swarming Republic forces in both battles for the planet.","image":"https://vignette.wikia.nocookie.net/starwars/images/8/85/GraviticDeflection-SWZ.png/revision/latest/scale-to-width-down/600?cb=20210106055030"},{"name":"Droid Tri-Fighter","rarity":"common","id":"droid-tri-fighter","subtitle":"Starships & Vehicles","details":"The droid tri-fighter was a fast Separatist interceptor with three curved arms around a central ball, armed with lasers and buzz droid missiles.","image":"https://vignette.wikia.nocookie.net/starwars/images/c/c2/DIS-T81.png/revision/latest/scale-to-width-down/600?cb=20240811155637"},{"name":"Belbullab-22 Starfighter","rarity":"common","id":"belbullab-22-starfighter","subtitle":"Starships & Vehicles","details":"The Belbullab-22 was a rugged Separatist heavy starfighter with triple laser cannons, built in the same Feethan Ottraw works as Grievous's own fighter.","image":"https://vignette.wikia.nocookie.net/starwars/images/0/02/Belbullab22StarfighterSquadron-SWM37.png/revision/latest/scale-to-width-down/600?cb=20240710133102"},{"name":"Soulless One","rarity":"common","id":"soulless-one","subtitle":"Starships & Vehicles","details":"Soulless One was General Grievous's customized Belbullab-22 starfighter, used to escape Utapau and remembered for its speed and powerful deflector shields.","image":"https://vignette.wikia.nocookie.net/starwars/images/b/b7/General_Grievous_XW2.png/revision/latest/scale-to-width-down/600?cb=20190402030700"},{"name":"Twilight","rarity":"common","id":"twilight","subtitle":"Starships & Vehicles","details":"The Twilight was Anakin Skywalker's battered G9 Rigger freighter, used for rescue missions with Ahsoka Tano and R2-D2 throughout the Clone Wars.","image":"https://vignette.wikia.nocookie.net/starwars/images/7/7e/TwilightAft-CGSWG.png/revision/latest/scale-to-width-down/600?cb=20250208024157"},{"name":"Trident Assault Ship","rarity":"common","id":"trident-assault-ship","subtitle":"Starships & Vehicles","details":"Trident-class assault ships were squid-like Separatist craft with drilling tentacles, used by Asajj Ventress to attack Kamino's cloning facilities.","image":"https://vignette.wikia.nocookie.net/starwars/images/c/ce/Trident-SWZ.png/revision/latest/scale-to-width-down/600?cb=20210623014215"},{"name":"Marauder Corvette","rarity":"common","id":"marauder-corvette","subtitle":"Starships & Vehicles","details":"Marauder-class corvettes were small, fast warships used for patrol and escort duties, armed for ship-to-ship combat despite their compact frame.","image":"https://vignette.wikia.nocookie.net/starwars/images/8/80/Marauder-EaW.jpg/revision/latest/scale-to-width-down/600?cb=20061112045734"},{"name":"Nightbrother","rarity":"common","id":"nightbrother","subtitle":"Starships & Vehicles","details":"The Nightbrother was a starfighter associated with the Nightbrothers of Dathomir, linked to warriors such as Savage Opress during the Clone Wars.","image":"https://vignette.wikia.nocookie.net/starwars/images/f/fe/MaulGauntletFighter-SWZ.png/revision/latest/scale-to-width-down/600?cb=20220320191546"},{"name":"Kom'rk Transport","rarity":"common","id":"komrk-transport","subtitle":"Starships & Vehicles","details":"The Kom'rk-class Mandalorian transport was a large Gauntlet fighter with rotating wings, used by Death Watch and Maul's forces to carry warriors into battle.","image":"https://vignette.wikia.nocookie.net/starwars/images/b/ba/Gauntlet_on_Mandalore.png/revision/latest/scale-to-width-down/600?cb=20230312035559"},{"name":"Nevarro","rarity":"common","id":"nevarro","subtitle":"Planets & Locations","details":"Nevarro is a volcanic frontier world of lava fields and a single town, where Din Djarin met Greef Karga, Kuiil's allies and an Imperial remnant.","image":"https://vignette.wikia.nocookie.net/starwars/images/b/b5/Lavafields.png/revision/latest/scale-to-width-down/600?cb=20220221031225"},{"name":"Sorgan","rarity":"common","id":"sorgan","subtitle":"Planets & Locations","details":"Sorgan is a quiet forest world of krill farmers where Din Djarin sheltered with Grogu, met Cara Dune, and defended a village from raiders with an AT-ST.","image":"https://vignette.wikia.nocookie.net/starwars/images/7/7a/Sorgan_Village_The_Mandalorian.png/revision/latest/scale-to-width-down/600?cb=20220217045543"},{"name":"Arvala-7","rarity":"common","id":"arvala-7","subtitle":"Planets & Locations","details":"Arvala-7 is a rugged desert world where Din Djarin found Grogu in a mercenary compound, battled a mudhorn, and received vital help from Kuiil.","image":"https://vignette.wikia.nocookie.net/starwars/images/d/d0/Arvala-7_surface.png/revision/latest/scale-to-width-down/600?cb=20220206222235"},{"name":"Tython","rarity":"common","id":"tython","subtitle":"Planets & Locations","details":"Tython is an ancient Jedi world where Grogu sat on the seeing stone atop a temple, reaching through the Force while Boba Fett and Fennec Shand fought nearby.","image":"https://vignette.wikia.nocookie.net/starwars/images/8/81/GroguMeditating-TMCh14.png/revision/latest/scale-to-width-down/600?cb=20201207065116"},{"name":"Morak","rarity":"common","id":"morak","subtitle":"Planets & Locations","details":"A jungle refinery world where the Empire processed volatile rhydonium in secret; Din Djarin entered its base in trooper armor to find Moff Gideon.","image":"https://vignette.wikia.nocookie.net/starwars/images/1/14/MorakE15.png/revision/latest/scale-to-width-down/600?cb=20201212045559"},{"name":"Lah'mu","rarity":"common","id":"lahmu","subtitle":"Planets & Locations","details":"A remote, muddy farming world of black sand and shallow seas, where Galen Erso hid with his family until Orson Krennic's death troopers found them.","image":"https://vignette.wikia.nocookie.net/starwars/images/9/94/Lahmu-full-SWCT.png/revision/latest/scale-to-width-down/600?cb=20181010053452"},{"name":"Wobani","rarity":"common","id":"wobani","subtitle":"Planets & Locations","details":"A bleak Imperial labor camp world of mud and prisons, where Jyn Erso served a sentence under an alias before Rebel agents broke her out in a raid.","image":"https://vignette.wikia.nocookie.net/starwars/images/c/c2/Wobani.png/revision/latest/scale-to-width-down/600?cb=20180130034302"},{"name":"Ring of Kafrene","rarity":"common","id":"ring-of-kafrene","subtitle":"Planets & Locations","details":"A crowded trading outpost built into an asteroid ring, where Cassian Andor met an informant and made a hard choice to protect the Rebellion's secret.","image":"https://vignette.wikia.nocookie.net/starwars/images/0/08/RingOfKafrene-TSWB.png/revision/latest/scale-to-width-down/483?cb=20250129015805"},{"name":"Takodana","rarity":"common","id":"takodana","subtitle":"Planets & Locations","details":"A green lake world home to Maz Kanata's castle, a neutral haven for smugglers and travelers where Rey heard the call of Luke Skywalker's lightsaber.","image":"https://vignette.wikia.nocookie.net/starwars/images/f/f6/Tak.png/revision/latest?cb=20251031035110"},{"name":"D'Qar","rarity":"common","id":"dqar","subtitle":"Planets & Locations","details":"A verdant Outer Rim world that housed the Resistance base; its fighters launched the attack that destroyed Starkiller Base and saved the Resistance.","image":"https://vignette.wikia.nocookie.net/starwars/images/f/f0/DQar_SWCT.png/revision/latest/scale-to-width-down/600?cb=20181010053100"},{"name":"Crait","rarity":"common","id":"crait","subtitle":"Planets & Locations","details":"A mineral world of white salt over red crystal, where the Resistance made its stand in an old Rebel base as Kylo Ren led the First Order's assault.","image":"https://vignette.wikia.nocookie.net/starwars/images/1/13/Crait_TLJVD.png/revision/latest/scale-to-width-down/600?cb=20190603071432"},{"name":"Pasaana","rarity":"common","id":"pasaana","subtitle":"Planets & Locations","details":"A desert world famed for the Festival of the Ancestors, where Rey, Finn and Poe searched the sands for a Sith wayfinder clue and met Lando Calrissian.","image":"https://vignette.wikia.nocookie.net/starwars/images/1/1b/Pasaana-TROSGG.png/revision/latest/scale-to-width-down/600?cb=20200321022322"},{"name":"Kijimi","rarity":"common","id":"kijimi","subtitle":"Planets & Locations","details":"A snowy mountain world of thieves and droidsmiths, where Babu Frik worked on C-3PO and the First Order later destroyed the city with a Star Destroyer.","image":"https://vignette.wikia.nocookie.net/starwars/images/4/4e/Kijimi-TROSTGG.png/revision/latest/scale-to-width-down/600?cb=20230804052601"},{"name":"Ajan Kloss","rarity":"common","id":"ajan-kloss","subtitle":"Planets & Locations","details":"A lush jungle moon that served as the Resistance base after Crait, where Leia Organa trained Rey and the fleet prepared for the final fight at Exegol.","image":"https://vignette.wikia.nocookie.net/starwars/images/a/a3/Ajan-Kloss-TROS-GG.png/revision/latest/scale-to-width-down/600?cb=20250106064537"},{"name":"Kef Bir","rarity":"common","id":"kef-bir","subtitle":"Planets & Locations","details":"An ocean moon of Endor covered in wreckage from the second Death Star, where Rey found a Sith wayfinder among the ruins and dueled Kylo Ren in the waves.","image":"https://vignette.wikia.nocookie.net/starwars/images/d/d8/KefBir.jpg/revision/latest/scale-to-width-down/600?cb=20200109213910"},{"name":"Batuu","rarity":"common","id":"batuu","subtitle":"Planets & Locations","details":"A remote outpost world at the edge of Wild Space, where Black Spire Outpost drew smugglers, Resistance spies and First Order patrols to its busy markets.","image":"https://vignette.wikia.nocookie.net/starwars/images/d/d3/Batuu-system.png/revision/latest/scale-to-width-down/600?cb=20200822003007"},{"name":"Chandrila","rarity":"common","id":"chandrila","subtitle":"Planets & Locations","details":"A peaceful Core world and homeworld of Mon Mothma, famed for its calm seas and old senate families; it served as capital world for the New Republic.","image":"https://vignette.wikia.nocookie.net/starwars/images/0/0c/Chandrila-AoRCR.png/revision/latest/scale-to-width-down/600?cb=20170222012047"},{"name":"Hosnian Prime","rarity":"common","id":"hosnian-prime","subtitle":"Planets & Locations","details":"Capital world of the New Republic, destroyed with its whole star system when Starkiller Base fired its superweapon across the galaxy in a single strike.","image":"https://vignette.wikia.nocookie.net/starwars/images/c/c9/HosnianPrime-Databank.png/revision/latest/scale-to-width-down/600?cb=20171113015859"},{"name":"Onderon","rarity":"common","id":"onderon","subtitle":"Planets & Locations","details":"A jungle world of walled cities and great beasts, where Saw Gerrera and his sister Steela led rebels against Separatist rule during the Clone Wars.","image":"https://vignette.wikia.nocookie.net/starwars/images/3/37/OnderonTVE.png/revision/latest?cb=20220314031710"},{"name":"Sundari","rarity":"common","id":"sundari","subtitle":"Planets & Locations","details":"The domed capital city of Mandalore, built inside a protective sphere against a ruined landscape, and seat of Duchess Satine Kryze's pacifist government.","image":"https://vignette.wikia.nocookie.net/starwars/images/0/05/SundariRuins.png/revision/latest/scale-to-width-down/600?cb=20250127050127"},{"name":"Concordia","rarity":"common","id":"concordia","subtitle":"Planets & Locations","details":"A moon of Mandalore covered in forests, where the warrior splinter group Death Watch hid in old mines and plotted to overthrow Duchess Satine's rule.","image":"https://vignette.wikia.nocookie.net/starwars/images/8/85/Concordia_TMCh18.png/revision/latest/scale-to-width-down/590?cb=20230312065314"},{"name":"Kalevala","rarity":"common","id":"kalevala","subtitle":"Planets & Locations","details":"A Mandalorian world of castles and misty seas, ancestral home of House Kryze, where Duchess Satine Kryze's family held its seat of power for generations.","image":"https://vignette.wikia.nocookie.net/starwars/images/f/f9/Kalevala-Space.png/revision/latest/scale-to-width-down/600?cb=20230302024844"},{"name":"Carlac","rarity":"common","id":"carlac","subtitle":"Planets & Locations","details":"A red-rock world where the Zygerrian slaver Darts D'Nar held captives, and where Obi-Wan Kenobi and Anakin Skywalker fought to free Togruta colonists.","image":"https://vignette.wikia.nocookie.net/starwars/images/6/6e/CarlacTVE.png/revision/latest?cb=20200122041533"},{"name":"Florrum","rarity":"common","id":"florrum","subtitle":"Planets & Locations","details":"A desert world of geysers and pirate camps, home base of Hondo Ohnaka's Weequay pirate gang, who captured Jedi and a Sith lord alike for ransom profit.","image":"https://vignette.wikia.nocookie.net/starwars/images/1/18/Florrum-BFR.png/revision/latest/scale-to-width-down/600?cb=20131020053306"},{"name":"Zygerria","rarity":"common","id":"zygerria","subtitle":"Planets & Locations","details":"Homeworld of the Zygerrians, a slaver empire built on ornate palaces and cruel markets, which the Republic confronted during a mission in the Clone Wars.","image":"https://vignette.wikia.nocookie.net/starwars/images/f/fb/Zygerria-SotR.png/revision/latest/scale-to-width-down/600?cb=20121129231007"},{"name":"Umbara","rarity":"common","id":"umbara","subtitle":"Planets & Locations","details":"A shadowy world of perpetual twilight and hostile wildlife, where clone troopers fought Umbaran militia under the reckless command of General Krell.","image":"https://vignette.wikia.nocookie.net/starwars/images/8/82/Umbara_TVE.png/revision/latest?cb=20211110071751"},{"name":"Training Remote","rarity":"common","id":"training-remote","subtitle":"Weapons, Artifacts & Tech","details":"A floating sphere that fires harmless sting bolts for lightsaber practice; Luke Skywalker trained against one aboard the Millennium Falcon, blindfolded.","image":"https://vignette.wikia.nocookie.net/starwars/images/0/09/TrainingRemote-SW100Objects.png/revision/latest/scale-to-width-down/600?cb=20230419233541"},{"name":"Blaster Pistol","rarity":"common","id":"blaster-pistol","subtitle":"Weapons, Artifacts & Tech","details":"The galaxy's common sidearm, firing bolts of energized gas; models range from Han Solo's heavy DL-44 to the elegant weapons carried by Naboo security.","image":"https://vignette.wikia.nocookie.net/starwars/images/e/e8/DC17HandBlaster-CGSWG.png/revision/latest/scale-to-width-down/600?cb=20241215051954"},{"name":"Ion Blaster","rarity":"common","id":"ion-blaster","subtitle":"Weapons, Artifacts & Tech","details":"A weapon that fires ionized energy to disable droids and machinery without lasting harm; Jawas carry ion blasters to stun and salvage wandering droids.","image":"https://vignette.wikia.nocookie.net/starwars/images/2/25/JawaIonBlaster-DB.png/revision/latest/scale-to-width-down/600?cb=20221116043650"},{"name":"Stun Cuffs","rarity":"common","id":"stun-cuffs","subtitle":"Weapons, Artifacts & Tech","details":"Restraints that bind a prisoner's wrists and deliver a disabling shock at resistance, used by Imperial and Republic forces alike to secure captives.","image":"https://vignette.wikia.nocookie.net/starwars/images/0/0d/JediBinders-TheAcolyte-Databank.png/revision/latest/scale-to-width-down/600?cb=20240630183023"},{"name":"Comlink","rarity":"common","id":"comlink","subtitle":"Weapons, Artifacts & Tech","details":"A handheld communicator carried across the galaxy for voice contact over short and long ranges; Jedi, soldiers and smugglers all rely on the small device.","image":"https://vignette.wikia.nocookie.net/starwars/images/e/eb/Hush-98_Comlink.png/revision/latest/scale-to-width-down/257?cb=20241223072943"},{"name":"Datapad","rarity":"common","id":"datapad","subtitle":"Weapons, Artifacts & Tech","details":"A slim portable computer for reading, records and controls, carried by officers, traders and students in nearly every city and starship in the galaxy.","image":"https://vignette.wikia.nocookie.net/starwars/images/4/41/Imperial_datapad.png/revision/latest/scale-to-width-down/495?cb=20161204113618"},{"name":"Macrobinoculars","rarity":"common","id":"macrobinoculars","subtitle":"Weapons, Artifacts & Tech","details":"Handheld viewing devices that magnify distant terrain and tag targets with range data; scouts on Hoth and Tatooine used them to watch for danger.","image":"https://vignette.wikia.nocookie.net/starwars/images/9/9b/MB450_macrobinoculars.png/revision/latest?cb=20130228054943"},{"name":"Jetpack","rarity":"common","id":"jetpack","subtitle":"Weapons, Artifacts & Tech","details":"A wearable thruster pack giving short bursts of flight; Mandalorian warriors and bounty hunters such as Boba Fett made the device a feared battlefield tool.","image":"https://vignette.wikia.nocookie.net/starwars/images/3/3b/BobaFettsZ-6Jetpack-SW100Objects.png/revision/latest/scale-to-width-down/600?cb=20230419230130"},{"name":"Grappling Hook","rarity":"common","id":"grappling-hook","subtitle":"Weapons, Artifacts & Tech","details":"A fired line and hook for climbing or swinging across gaps; Luke Skywalker used one to swing with Leia across the Death Star's deep detention chasm.","image":"https://vignette.wikia.nocookie.net/starwars/images/0/02/GrapplingHook-OutlawsVCG.png/revision/latest/scale-to-width-down/448?cb=20240619015934"},{"name":"Restraining Bolt","rarity":"common","id":"restraining-bolt","subtitle":"Weapons, Artifacts & Tech","details":"A small device fitted to a droid that forces obedience and blocks escape; Jawas fitted them to R2-D2 and C-3PO after capturing the pair on Tatooine.","image":"https://vignette.wikia.nocookie.net/starwars/images/8/84/Droid_Restraining_Bolt.png/revision/latest/scale-to-width-down/583?cb=20230418140004"},{"name":"Carbonite Freezing","rarity":"common","id":"carbonite-freezing","subtitle":"Weapons, Artifacts & Tech","details":"A process that seals a subject in a metal block for transport or storage; Darth Vader tested it on Han Solo in Cloud City, who survived in hibernation.","image":"https://vignette.wikia.nocookie.net/starwars/images/8/8c/CarbonFreezingRex-TC.png/revision/latest/scale-to-width-down/600?cb=20130526231519"},{"name":"Bacta Tank","rarity":"common","id":"bacta-tank","subtitle":"Weapons, Artifacts & Tech","details":"A medical tank filled with healing bacta fluid; Luke Skywalker recovered inside one on Hoth, and injured troopers across the galaxy healed the same way.","image":"https://vignette.wikia.nocookie.net/starwars/images/3/3d/Bactatankbreathmask.jpg/revision/latest?cb=20080123023106"},{"name":"Hologram Projector","rarity":"common","id":"hologram-projector","subtitle":"Weapons, Artifacts & Tech","details":"A device that projects three-dimensional images for messages and briefings, from Princess Leia's plea for help to war-room maps of enemy star fleets.","image":"https://vignette.wikia.nocookie.net/starwars/images/2/26/AstromechHoloprojector-SW100Objects.png/revision/latest/scale-to-width-down/600?cb=20231108012520"},{"name":"Tracer Beacon","rarity":"common","id":"tracer-beacon","subtitle":"Weapons, Artifacts & Tech","details":"A small tracking device planted on a ship to follow its course through hyperspace; a homing beacon led the Empire straight to the Rebel base on Yavin 4.","image":"https://vignette.wikia.nocookie.net/starwars/images/2/21/S-threadtransmitterbracelet-TLJVD.png/revision/latest?cb=20230729025521"},{"name":"Thermal Imploder","rarity":"common","id":"thermal-imploder","subtitle":"Weapons, Artifacts & Tech","details":"A devastating Imperial weapon that collapses matter inward in a crushing blast; its test firing on a jungle target left a crater of twisted wreckage.","image":"https://vignette.wikia.nocookie.net/starwars/images/0/00/Thermal_Imploders_BF.png/revision/latest/scale-to-width-down/600?cb=20161022180724"},{"name":"Proton Torpedo","rarity":"common","id":"proton-torpedo","subtitle":"Weapons, Artifacts & Tech","details":"A guided warhead carried by starfighters, able to turn sharp corners at speed; Luke Skywalker's torpedoes destroyed the first Death Star at Yavin.","image":"https://vignette.wikia.nocookie.net/starwars/images/3/31/Protontorpedo.jpg/revision/latest/scale-to-width-down/600?cb=20080317212011"},{"name":"Deflector Shield","rarity":"common","id":"deflector-shield","subtitle":"Weapons, Artifacts & Tech","details":"An energy barrier that protects ships, bases and even whole cities from fire and debris; shield generators guarded the Rebel base on Hoth from orbit.","image":"https://vignette.wikia.nocookie.net/starwars/images/8/8b/Shield_must_be_deactivated.png/revision/latest/scale-to-width-down/600?cb=20130404034405"},{"name":"Tractor Beam","rarity":"common","id":"tractor-beam","subtitle":"Weapons, Artifacts & Tech","details":"A projected force that pulls and holds objects or ships at a distance; the Death Star used one to capture the Millennium Falcon and draw it inside.","image":"https://vignette.wikia.nocookie.net/starwars/images/8/81/InterstellarTug-BI.png/revision/latest/scale-to-width-down/600?cb=20120902054844"},{"name":"Kyber Crystal Shard","rarity":"common","id":"kyber-crystal-shard","subtitle":"Weapons, Artifacts & Tech","details":"A fragment of the living crystal that powers every lightsaber and focuses great weapons; even a small shard hums with a deep connection to the Force.","image":"https://vignette.wikia.nocookie.net/starwars/images/4/43/KyberCrystal-SW100Objects.png/revision/latest/scale-to-width-down/600?cb=20230516015956"},{"name":"Acklay","rarity":"common","id":"acklay","subtitle":"Creatures & Species","details":"A huge crustacean predator with six spindly legs, sharp claws and a beaked maw; one stalked Obi-Wan Kenobi through the Geonosian arena execution bout.","image":"https://vignette.wikia.nocookie.net/starwars/images/e/e2/Acklay.png/revision/latest/scale-to-width-down/600?cb=20200427021451"},{"name":"Nexu","rarity":"common","id":"nexu","subtitle":"Creatures & Species","details":"A sleek feline predator with four eyes, quills and a split tail, kept for arena spectacles on Geonosis; one clawed Padmé Amidala in the execution arena.","image":"https://vignette.wikia.nocookie.net/starwars/images/5/5c/Bestial_Fury_SM.png/revision/latest/scale-to-width-down/600?cb=20170604231845"},{"name":"Reek","rarity":"common","id":"reek","subtitle":"Creatures & Species","details":"A massive horned beast used as an arena execution animal on Geonosis, charging at chained prisoners; Anakin Skywalker calmed one through the Force there.","image":"https://vignette.wikia.nocookie.net/starwars/images/8/8e/Reek.jpg/revision/latest/scale-to-width-down/600?cb=20091202161701"},{"name":"Varactyl","rarity":"common","id":"varactyl","subtitle":"Creatures & Species","details":"A swift feathered reptile from Utapau with sure-footed claws for rock walls; Obi-Wan Kenobi rode the loyal Boga in his hunt for General Grievous.","image":"https://vignette.wikia.nocookie.net/starwars/images/3/38/BogaLoyalVaractyl-Homeworlds.png/revision/latest/scale-to-width-down/600?cb=20261009045833"},{"name":"Aiwha","rarity":"common","id":"aiwha","subtitle":"Creatures & Species","details":"A winged aquatic creature from Kamino that swims and flies between the stilt cities; Tipoca City's cloners rode aiwhas above the planet's endless storms.","image":"https://vignette.wikia.nocookie.net/starwars/images/b/b6/Aiwha-TVE.png/revision/latest/scale-to-width-down/600?cb=20220226023118"},{"name":"Fathier","rarity":"common","id":"fathier","subtitle":"Creatures & Species","details":"A tall, swift racing animal bred for speed on tracks like Canto Bight, where wealthy gamblers wagered fortunes and stable children dreamed of freedom.","image":"https://vignette.wikia.nocookie.net/starwars/images/d/d1/Father-TLJTUG.png/revision/latest/scale-to-width-down/600?cb=20240106045413"},{"name":"Loth-Cat","rarity":"common","id":"loth-cat","subtitle":"Creatures & Species","details":"A small temperamental feline native to Lothal, fond of naps and quick to bare its teeth; the creatures often crossed paths with Ezra Bridger and his friends.","image":"https://vignette.wikia.nocookie.net/starwars/images/2/2d/LothCat-TVE.png/revision/latest/scale-to-width-down/600?cb=20211115035158"},{"name":"Loth-Wolf","rarity":"common","id":"loth-wolf","subtitle":"Creatures & Species","details":"A rare, majestic wolf of Lothal with a deep bond to the Force; the great wolves guided Ezra Bridger and carried warnings about the fate of his homeworld.","image":"https://vignette.wikia.nocookie.net/starwars/images/c/ce/Loth-wolf_pack_WaaD.png/revision/latest/scale-to-width-down/600?cb=20180905005816"},{"name":"Puffer Pig","rarity":"common","id":"puffer-pig","subtitle":"Creatures & Species","details":"A rotund animal with a keen nose for precious minerals that inflates when frightened; Lando Calrissian kept one aboard his ship for prospecting work.","image":"https://vignette.wikia.nocookie.net/starwars/images/6/6f/Appraise-EaW.png/revision/latest/scale-to-width-down/600?cb=20211109052000"},{"name":"Happabore","rarity":"common","id":"happabore","subtitle":"Creatures & Species","details":"A huge, gentle hauling beast with a broad snout and tough hide, used as a pack animal on Jakku; one blocked Rey's path at Niima Outpost in a standoff.","image":"https://vignette.wikia.nocookie.net/starwars/images/e/ee/HappaborePup-WheresTheWookieeDeluxe.jpg/revision/latest/scale-to-width-down/600?cb=20230116203522"},{"name":"Rathtar","rarity":"common","id":"rathtar","subtitle":"Creatures & Species","details":"A fast, tentacled predator with a gaping maw, hunted at great risk for collectors; Han Solo hauled rathtars aboard his freighter for King Prana's zoo.","image":"https://vignette.wikia.nocookie.net/starwars/images/b/b9/Rathtar_eravana.png/revision/latest/scale-to-width-down/600?cb=20160814054433"},{"name":"Vulptex","rarity":"common","id":"vulptex","subtitle":"Creatures & Species","details":"A crystalline fox of Crait whose coat of sharp crystal bristles grew from the salt world's minerals; a skulk of them led the Resistance to an escape route.","image":"https://vignette.wikia.nocookie.net/starwars/images/f/fb/Vulptex_2.png/revision/latest/scale-to-width-down/600?cb=20171121062844"},{"name":"Orbak","rarity":"common","id":"orbak","subtitle":"Creatures & Species","details":"A tusked, horse-like riding animal from Pasaana, swift across open desert; Resistance fighters rode orbaks in a bold charge along a Star Destroyer hull.","image":"https://vignette.wikia.nocookie.net/starwars/images/2/26/Orbak.jpg/revision/latest/scale-to-width-down/600?cb=20200503174637"},{"name":"Blurrg","rarity":"common","id":"blurrg","subtitle":"Creatures & Species","details":"A sturdy two-legged riding beast used by farmers and fighters on worlds like Ryloth and Arvala-7, where Kuiil kept blurrgs and taught Din Djarin to ride.","image":"https://vignette.wikia.nocookie.net/starwars/images/3/35/Syndulla_charge.png/revision/latest/scale-to-width-down/600?cb=20121005170757"},{"name":"Kowakian Monkey-Lizard","rarity":"common","id":"kowakian-monkey-lizard","subtitle":"Creatures & Species","details":"A mischievous reptilian creature famed for its shrill cackling laugh; Salacious Crumb perched in Jabba the Hutt's palace, mocking the crime lord's victims.","image":"https://vignette.wikia.nocookie.net/starwars/images/2/24/PilfMukmukRelic-SWGoH.png/revision/latest/scale-to-width-down/600?cb=20251003043830"},{"name":"Mynock","rarity":"common","id":"mynock","subtitle":"Creatures & Species","details":"A leathery parasite that clings to starship hulls and chews power cables; mynocks infested the space slug's belly where the Millennium Falcon once hid.","image":"https://vignette.wikia.nocookie.net/starwars/images/9/9c/Mynock-AA.png/revision/latest?cb=20200427023903"},{"name":"Purrgil","rarity":"common","id":"purrgil","subtitle":"Creatures & Species","details":"Gigantic space whales that travel through hyperspace on their own power; Ezra Bridger befriended them, and their migration inspired early hyperdrive travel.","image":"https://vignette.wikia.nocookie.net/starwars/images/c/c1/Purrgil_ready_to_jump.png/revision/latest/scale-to-width-down/600?cb=20160211171904"},{"name":"Star Wars: The Clone Wars","rarity":"common","id":"star-wars-the-clone-wars","subtitle":"Films & Series","details":"An animated series following Anakin Skywalker, Obi-Wan Kenobi and Ahsoka Tano through the Clone Wars, from Christophsis to the siege of Mandalore.","image":"https://vignette.wikia.nocookie.net/starwars/images/d/dd/SWTCW-poster.jpg/revision/latest/scale-to-width-down/600?cb=20070518031445"},{"name":"Star Wars Rebels","rarity":"common","id":"star-wars-rebels","subtitle":"Films & Series","details":"An animated series following Ezra Bridger and the Ghost crew on Lothal, as a small rebel cell grows into part of the wider fight against the Empire.","image":"https://vignette.wikia.nocookie.net/starwars/images/a/a6/RebelsPoster.png/revision/latest/scale-to-width-down/600?cb=20140805200015"},{"name":"Obi-Wan Kenobi (Series)","rarity":"common","id":"obi-wan-kenobi-series","subtitle":"Films & Series","details":"A series following Obi-Wan Kenobi in exile on Tatooine a decade after the fall of the Jedi, drawn out to rescue a young Leia Organa from Inquisitors.","image":"https://vignette.wikia.nocookie.net/starwars/images/f/f8/ObiWanKenobiOfficialPoster.png/revision/latest/scale-to-width-down/600?cb=20220713044431"},{"name":"Ahsoka (Series)","rarity":"common","id":"ahsoka-series","subtitle":"Films & Series","details":"A series following Ahsoka Tano after the fall of the Empire as she hunts for Grand Admiral Thrawn and the lost Ezra Bridger across two galaxies.","image":"https://vignette.wikia.nocookie.net/starwars/images/3/39/Ahsoka_Official_Poster.jpg/revision/latest/scale-to-width-down/600?cb=20230407134006"},{"name":"Star Wars Holiday Special","rarity":"common","id":"star-wars-holiday-special","subtitle":"Films & Series","details":"A television special built around Chewbacca's family on Kashyyyk celebrating Life Day, remembered for introducing the bounty hunter Boba Fett in animation.","image":"https://vignette.wikia.nocookie.net/starwars/images/2/23/StarWarsHS.jpg/revision/latest?cb=20060417210458"},{"name":"Caravan of Courage: An Ewok Adventure","rarity":"common","id":"caravan-of-courage-an-ewok-adventure","subtitle":"Films & Series","details":"A television film following the Towani children on Endor, who join Wicket and the Ewoks to rescue their parents from the giant Gorax in its mountain lair.","image":"https://vignette.wikia.nocookie.net/starwars/images/6/60/Caravan_bg.jpg/revision/latest/scale-to-width-down/600?cb=20140228114152"},{"name":"Ewoks: The Battle for Endor","rarity":"common","id":"ewoks-the-battle-for-endor","subtitle":"Films & Series","details":"A television film in which young Cindel and Wicket flee the warlock Terak's raiders, finding shelter with the hermit Noa in the forests of Endor.","image":"https://vignette.wikia.nocookie.net/starwars/images/a/ad/Ilm-ewok2.jpg/revision/latest/scale-to-width-down/600?cb=20051107095944"},{"name":"Podrace on Tatooine","rarity":"common","id":"podrace-on-tatooine","subtitle":"Battles & Iconic Moments","details":"The Boonta Eve Classic podrace at Mos Espa, where young Anakin Skywalker raced Sebulba and rival pilots at deadly speed to win his freedom from slavery.","image":"https://vignette.wikia.nocookie.net/starwars/images/9/94/FlagParade-TPM.png/revision/latest/scale-to-width-down/600?cb=20130118055347"},{"name":"Escape from the Death Star","rarity":"common","id":"escape-from-the-death-star","subtitle":"Battles & Iconic Moments","details":"Luke Skywalker, Han Solo and Chewbacca rescued Princess Leia from her cell in stormtrooper disguise, escaping through a garbage masher and swarms of guards.","image":"https://vignette.wikia.nocookie.net/starwars/images/2/2f/FalconDeathStarEscape.jpg/revision/latest/scale-to-width-down/600?cb=20211012100927"},{"name":"Battle of Christophsis","rarity":"common","id":"battle-of-christophsis","subtitle":"Battles & Iconic Moments","details":"An early Clone Wars battle for the crystal world Christophsis, where Anakin Skywalker met his new Padawan, Ahsoka Tano, amid a Separatist invasion.","image":"https://vignette.wikia.nocookie.net/starwars/images/5/5c/Battle_of_Christophsis.png/revision/latest/scale-to-width-down/600?cb=20121013044237"},{"name":"Duel of the Fates","rarity":"common","id":"duel-of-the-fates","subtitle":"Battles & Iconic Moments","details":"The lightsaber duel in which Qui-Gon Jinn and Obi-Wan Kenobi fought Darth Maul through Naboo's power generator, ending with Qui-Gon's mortal wounding.","image":"https://vignette.wikia.nocookie.net/starwars/images/0/09/Qui-Gon_vs_Maul.png/revision/latest/scale-to-width-down/600?cb=20130120033534"},{"name":"Liberation of Lothal","rarity":"common","id":"liberation-of-lothal","subtitle":"Battles & Iconic Moments","details":"The Ghost crew's final campaign freed Lothal from Imperial rule, as Ezra Bridger faced Grand Admiral Thrawn and vanished with him into deep space.","image":"https://vignette.wikia.nocookie.net/starwars/images/8/8c/SWR_Liberation_of_Lothal.png/revision/latest/scale-to-width-down/600?cb=20180306070447"}];
  extra.forEach(function (x) {
    if (S.byId.has(x.id)) return;
    var c = { id: x.id, num: S.cards.length + 1, name: x.name, rarity: x.rarity,
              subtitle: x.subtitle, details: x.details, image: x.image, logo: '' };
    S.cards.push(c);
    S.byId.set(c.id, c);
    if (S.pools[c.rarity]) S.pools[c.rarity].push(c);
  });
})();
